import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import gcmfast
_enc = gcmfast.encrypt
_getrc = sys.getrefcount

class Solver:
    def __init__(self):
        self._pool = []
    def solve(self, problem, **kwargs):
        ad = problem["associated_data"]
        if ad is None:
            ad = b""
        pt = problem["plaintext"]
        n = len(pt)
        buf = None
        pool = self._pool
        for i, b in enumerate(pool):
            # only reuse a buffer that nobody outside the pool references
            if len(b) == n and _getrc(b) <= 3:
                buf = pool.pop(i)
                break
            b = None
        if buf is not None:
            c, t = _enc(problem["key"], problem["nonce"], pt, ad, 8, buf)
        else:
            c, t = _enc(problem["key"], problem["nonce"], pt, ad, 8)
        pool.append(c)
        if len(pool) > 3:
            pool.pop(0)
        return {"ciphertext": c, "tag": t}

